// Auto-generated WebSphere PMI Metrics & Logs Documentation (Bilingual EN + HI)
export const wasMonitoringDocsPages = {
  "step0": {
    "id": "step0",
    "title": "1.1: Install Prometheus & Grafana",
    "title_hi": "1.1: Prometheus aur Grafana Install Karein",
    "subtitle": "Prerequisites: Downloading and installing the metrics collection database and visualization servers.",
    "subtitle_hi": "Prerequisites: Metrics collection database (Prometheus) aur visualization dashboard server (Grafana) download aur setup karna.",
    "html": "<h1>1.1: Install Prometheus & Grafana</h1>\n            <p class=\"page-subtitle\">Prerequisites: Downloading and installing the metrics collection database and visualization servers.</p>\n            \n            <section>\n              <h2>Installation on Windows</h2>\n              <p>To monitor your application environment, you must deploy Prometheus to collect timeseries data and Grafana to serve dashboard visualizations.</p>\n              \n              <h3>1. Setup Prometheus Database</h3>\n              <p>Download the latest Windows ZIP archive containing the Prometheus engine.</p>\n              <ul>\n                <li>Go to: <a href=\"https://prometheus.io/download/\" target=\"_blank\">Prometheus Downloads <i class=\"fa-solid fa-up-right-from-square\" style=\"font-size: 0.75rem;\"></i></a></li>\n                <li>Extract the archive payload to a local partition folder, for example: <code>A:\\prometheus</code></li>\n              </ul>\n\n              <h3>2. Setup Grafana Server</h3>\n              <p>Download the Windows MSI installer to run Grafana as a system background service.</p>\n              <ul>\n                <li>Go to: <a href=\"https://grafana.com/grafana/download?platform=windows\" target=\"_blank\">Grafana Downloads <i class=\"fa-solid fa-up-right-from-square\" style=\"font-size: 0.75rem;\"></i></a></li>\n                <li>Complete the installation wizard. By default, the interface runs on: <code>http://localhost:3000</code></li>\n              </ul>\n\n              <h2>Managing the Grafana Service</h2>\n              <p>Control the startup states of your Grafana installation based on the deploy method:</p>\n\n              <div class=\"ibm-tabs\">\n                <button class=\"ibm-tab-btn active\" onclick=\"switchTab('msi', this)\">Windows Service (MSI)</button>\n                <button class=\"ibm-tab-btn\" onclick=\"switchTab('zip', this)\">Standalone Binary (ZIP)</button>\n              </div>\n              \n              <div id=\"tab-msi\" class=\"ibm-tab-pane active\">\n                <p>Grafana runs as a background Windows Service. Run PowerShell with Administrator privileges:</p>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>PowerShell (Admin)</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('Start-Service -Name \\&quot;Grafana\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>Start-Service -Name \"Grafana\"</pre>\n                </div>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>PowerShell (Admin)</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('Stop-Service -Name \\&quot;Grafana\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>Stop-Service -Name \"Grafana\"</pre>\n                </div>\n              </div>\n\n              <div id=\"tab-zip\" class=\"ibm-tab-pane\">\n                <p>Start Grafana via command-line execution:</p>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>Command Prompt</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('cd C:\\\\grafana\\\\bin\\n.\\\\grafana-server.exe', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>cd C:\\grafana\\bin\n.\\grafana-server.exe</pre>\n                </div>\n                <p><strong>To Stop:</strong> Press <code>Ctrl + C</code> in the terminal window running the execution script.</p>\n              </div>\n            </section>",
    "html_hi": "<h1>1.1: Prometheus aur Grafana Install Karein</h1>\n            <p class=\"page-subtitle\">Prerequisites: Metrics database (Prometheus) aur dashboard server (Grafana) download aur setup karna.</p>\n            \n            <section>\n              <h2>Windows par Installation Guide</h2>\n              <p>Apne WebSphere application environment ko properly monitor karne ke liye, hum Prometheus (time-series metrics database) aur Grafana (dashboard visualization server) deploy karte hain.</p>\n              \n              <h3>1. Prometheus Database Setup Karein</h3>\n              <p>Prometheus official site se latest Windows ZIP archive download karein:</p>\n              <ul>\n                <li>Download link: <a href=\"https://prometheus.io/download/\" target=\"_blank\">Prometheus Downloads <i class=\"fa-solid fa-up-right-from-square\" style=\"font-size: 0.75rem;\"></i></a></li>\n                <li>Archive ko apne local folder mein extract karein, jaise: <code>A:\\prometheus</code></li>\n              </ul>\n\n              <h3>2. Grafana Server Setup Karein</h3>\n              <p>Grafana ko Windows background service ke roop me run karne ke liye Windows MSI installer download karein:</p>\n              <ul>\n                <li>Download link: <a href=\"https://grafana.com/grafana/download?platform=windows\" target=\"_blank\">Grafana Downloads <i class=\"fa-solid fa-up-right-from-square\" style=\"font-size: 0.75rem;\"></i></a></li>\n                <li>Installation wizard complete karein. By default Grafana <code>http://localhost:3000</code> par run hota hai.</li>\n              </ul>\n\n              <h2>Grafana Service Manage Karne Ka Tareeqa</h2>\n              <p>Aapne jis method se Grafana deploy kiya hai, uske according service start ya stop karein:</p>\n\n              <div class=\"ibm-tabs\">\n                <button class=\"ibm-tab-btn active\" onclick=\"switchTab('msi', this)\">Windows Service (MSI)</button>\n                <button class=\"ibm-tab-btn\" onclick=\"switchTab('zip', this)\">Standalone Binary (ZIP)</button>\n              </div>\n              \n              <div id=\"tab-msi\" class=\"ibm-tab-pane active\">\n                <p>Agar MSI installer se setup kiya hai, toh Administrator PowerShell me yeh commands run karein:</p>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>PowerShell (Admin)</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('Start-Service -Name \\&quot;Grafana\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>Start-Service -Name \"Grafana\"</pre>\n                </div>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>PowerShell (Admin)</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('Stop-Service -Name \\&quot;Grafana\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>Stop-Service -Name \"Grafana\"</pre>\n                </div>\n              </div>\n\n              <div id=\"tab-zip\" class=\"ibm-tab-pane\">\n                <p>Agar ZIP standalone binary use kar rahe hain, toh command prompt me start karein:</p>\n                <div class=\"ibm-code-block\">\n                  <div class=\"ibm-code-header\">\n                    <span>Command Prompt</span>\n                    <button class=\"btn-copy\" onclick=\"copyText('cd C:\\\\grafana\\\\bin\\n.\\\\grafana-server.exe', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                  </div>\n                  <pre>cd C:\\grafana\\bin\n.\\grafana-server.exe</pre>\n                </div>\n                <p><strong>Stop karne ke liye:</strong> Terminal window me <code>Ctrl + C</code> press karein.</p>\n              </div>\n            </section>"
  },
  "step1": {
    "id": "step1",
    "title": "1.2: Enable Performance Monitoring Infrastructure (PMI)",
    "title_hi": "1.2: WebSphere Console me PMI Enable Karein",
    "subtitle": "Configure the WAS console to gather performance timeseries data.",
    "subtitle_hi": "Performance timeseries data collect karne ke liye WebSphere console configure karein.",
    "html": "<h1>1.2: Enable Performance Monitoring Infrastructure (PMI)</h1>\n            <p class=\"page-subtitle\">Configure the WAS console to gather performance timeseries data.</p>\n            \n            <section>\n              <h2>Procedure</h2>\n              <p>WebSphere Traditional requires that Performance Monitoring Infrastructure (PMI) is explicitly enabled to expose resource and memory statistics.</p>\n              \n              <div class=\"ibm-callout\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-check\"></i> Status Confirmed</div>\n                <div class=\"ibm-callout-content\">\n                  <p>We verified that your local server instance already has PMI configured at the <strong>Basic</strong> level. No additional modifications are needed.</p>\n                </div>\n              </div>\n\n              <ol>\n                <li>Open the WebSphere administrative console at <a href=\"https://localhost:9043/ibm/console\" target=\"_blank\">https://localhost:9043/ibm/console</a>.</li>\n                <li>Navigate to **Monitoring and Tuning** &gt; **Performance Monitoring Infrastructure (PMI)** in the tree layout.</li>\n                <li>Select your server node (e.g. <code>server1</code> or <code>MXSERVER</code>).</li>\n                <li>Under the **Configuration** panel, ensure **Enable Performance Monitoring Infrastructure (PMI)** is checked.</li>\n                <li>Set the statistic set to **Basic** or **Custom**, save changes, and synchronize nodes.</li>\n              </ol>\n            </section>",
    "html_hi": "<h1>1.2: WebSphere Console me PMI Enable Karein</h1>\n            <p class=\"page-subtitle\">Performance timeseries metrics collect karne ke liye WebSphere Traditional console configure karein.</p>\n            \n            <section>\n              <h2>Step-by-Step Procedure</h2>\n              <p>WebSphere Traditional JVM memory, thread pools, aur JDBC connection pools ke live statistics expose karne ke liye PMI (Performance Monitoring Infrastructure) ka enable hona zaroori hai.</p>\n              \n              <div class=\"ibm-callout\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-check\"></i> Status Confirmed</div>\n                <div class=\"ibm-callout-content\">\n                  <p>Aapke local server instance par PMI pehle se <strong>Basic</strong> level par configured aur active hai. Additional changes ki zaroorat nahi hai.</p>\n                </div>\n              </div>\n\n              <ol>\n                <li>WebSphere Admin Console open karein: <a href=\"https://localhost:9043/ibm/console\" target=\"_blank\">https://localhost:9043/ibm/console</a></li>\n                <li>Left navigation tree mein **Monitoring and Tuning** &gt; **Performance Monitoring Infrastructure (PMI)** par jayein.</li>\n                <li>Apna target application server select karein (jaise <code>server1</code> ya <code>MXSERVER</code>).</li>\n                <li>**Configuration** tab ke andar **Enable Performance Monitoring Infrastructure (PMI)** checkbox ko check karein.</li>\n                <li>Statistic set ko **Basic** ya **Custom** select karke Save karein aur nodes synchronize karein.</li>\n              </ol>\n            </section>"
  },
  "step2": {
    "id": "step2",
    "title": "1.3: Deploy the Native metrics.ear Application",
    "title_hi": "1.3: Native metrics.ear Application Deploy Karein",
    "subtitle": "Configure WebSphere to serve metrics payload for Prometheus scraping.",
    "subtitle_hi": "Prometheus scraping ke liye WebSphere metrics endpoint (/metrics) expose karein.",
    "html": "<h1>1.3: Deploy the Native metrics.ear Application</h1>\n            <p class=\"page-subtitle\">Configure WebSphere to serve metrics payload for Prometheus scraping.</p>\n            \n            <section>\n              <h2>About metrics.ear</h2>\n              <p>WebSphere Traditional includes a pre-packaged enterprise archive <code>metrics.ear</code> that queries PMI data internally and maps it to a standard Prometheus metrics format.</p>\n              \n              <h3>1. Locate metrics.ear</h3>\n              <p>The archive is distributed inside the standard WAS installation path:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>Path</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('C:\\\\IBM\\\\WebSphere\\\\AppServer\\\\installableApps\\\\metrics.ear', this)\"><i class=\"fa-regular fa-copy\"></i> Copy Path</button>\n                </div>\n                <pre>C:\\IBM\\WebSphere\\AppServer\\installableApps\\metrics.ear</pre>\n              </div>\n\n              <h3>2. Deploy metrics application</h3>\n              <ol>\n                <li>Navigate to **Applications** &gt; **New Application** &gt; **New Enterprise Application** in the WAS console.</li>\n                <li>Browse and upload the <code>metrics.ear</code> archive. Click **Next**.</li>\n                <li>Select **Fast Path** installation. Click **Next** and accept default binding steps.</li>\n                <li>\n                  <strong>Module Server Mapping:</strong> In the \"Map modules to servers\" step, select the <code>metrics</code> module, check the target application servers (such as <code>MXSERVER</code> or <code>server1</code>), and apply mappings.\n                </li>\n                <li>Complete the installation. Save and apply updates directly to the master repository.</li>\n                <li>Start the <code>metrics</code> application from the enterprise applications listing panel.</li>\n              </ol>\n\n              <div class=\"ibm-callout\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-info\"></i> Target Endpoints</div>\n                <div class=\"ibm-callout-content\">\n                  <p>Verify that your applications are running and returning raw metrics payloads:</p>\n                  <ul style=\"margin-top: 0.5rem; margin-bottom: 0;\">\n                    <li>MXSERVER: <code>http://localhost:9084/metrics</code></li>\n                    <li>Server 1: <code>http://localhost:9081/metrics</code></li>\n                  </ul>\n                </div>\n              </div>\n            </section>",
    "html_hi": "<h1>1.3: Native metrics.ear Application Deploy Karein</h1>\n            <p class=\"page-subtitle\">Prometheus scraping ke liye WebSphere metrics endpoint (/metrics) expose karein.</p>\n            \n            <section>\n              <h2>metrics.ear kya hai?</h2>\n              <p>WebSphere Traditional ke sath built-in enterprise archive <code>metrics.ear</code> aati hai jo PMI internal data ko Prometheus ke standard text format mein convert karke <code>/metrics</code> endpoint par serve karti hai.</p>\n              \n              <h3>1. metrics.ear File Locate Karein</h3>\n              <p>Yeh package WAS installable apps folder mein directly milta hai:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>File Location Path</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('C:\\\\IBM\\\\WebSphere\\\\AppServer\\\\installableApps\\\\metrics.ear', this)\"><i class=\"fa-regular fa-copy\"></i> Copy Path</button>\n                </div>\n                <pre>C:\\IBM\\WebSphere\\AppServer\\installableApps\\metrics.ear</pre>\n              </div>\n\n              <h3>2. Enterprise Application Deploy Karein</h3>\n              <ol>\n                <li>WAS Admin Console mein **Applications** &gt; **New Application** &gt; **New Enterprise Application** par jayein.</li>\n                <li><code>metrics.ear</code> file select karke **Next** click karein.</li>\n                <li>**Fast Path** select karke default options ke sath aage badhein.</li>\n                <li>\n                  <strong>Map modules to servers:</strong> <code>metrics</code> module ko select karein, apne target server (jaise <code>MXSERVER</code> ya <code>server1</code>) ko check karein aur Apply karein.\n                </li>\n                <li>Install finish karein aur changes ko master repository mein Save karein.</li>\n                <li>Enterprise Applications list se <code>metrics</code> application ko **Start** karein.</li>\n              </ol>\n\n              <div class=\"ibm-callout\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-info\"></i> Endpoints Verification</div>\n                <div class=\"ibm-callout-content\">\n                  <p>Browser me verify karein ki raw Prometheus metrics data render ho raha hai:</p>\n                  <ul style=\"margin-top: 0.5rem; margin-bottom: 0;\">\n                    <li>MXSERVER Endpoint: <code>http://localhost:9084/metrics</code></li>\n                    <li>Server 1 Endpoint: <code>http://localhost:9081/metrics</code></li>\n                  </ul>\n                </div>\n              </div>\n            </section>"
  },
  "step3": {
    "id": "step3",
    "title": "1.4: Configure & Start Prometheus",
    "title_hi": "1.4: Prometheus Configure aur Start Karein",
    "subtitle": "Scrape telemetry endpoints into the local database.",
    "subtitle_hi": "WebSphere metrics endpoints ko scrape karke local Prometheus database me store karein.",
    "html": "<h1>1.4: Configure & Start Prometheus</h1>\n            <p class=\"page-subtitle\">Scrape telemetry endpoints into the local database.</p>\n            \n            <section>\n              <h2>Configure prometheus.yml</h2>\n              <p>Open the configuration file <code>prometheus.yml</code> inside the extracted Prometheus directory and define the targets as follows:</p>\n\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>prometheus.yml</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('global:\\n  scrape_interval: 15s\\n  evaluation_interval: 15s\\n\\nscrape_configs:\\n  - job_name: \\&quot;prometheus\\&quot;\\n    static_configs:\\n      - targets: [\\&quot;localhost:9090\\&quot;]\\n\\n  - job_name: \\&quot;websphere-mxserver\\&quot;\\n    metrics_path: \\&quot;/metrics\\&quot;\\n    scheme: \\&quot;http\\&quot;\\n    static_configs:\\n      - targets:\\n          - \\&quot;localhost:9084\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy Config</button>\n                </div>\n                <pre>global:\n  scrape_interval: 15s\n  evaluation_interval: 15s\n\nscrape_configs:\n  - job_name: \"prometheus\"\n    static_configs:\n      - targets: [\"localhost:9090\"]\n\n  - job_name: 'websphere-mxserver'\n    metrics_path: '/metrics'\n    scheme: 'http'\n    static_configs:\n      - targets:\n          - 'localhost:9084'</pre>\n              </div>\n\n              <h2>Setup Windows Background Service</h2>\n              <p>Deploy the Prometheus executable as a background service using the NSSM wrapper:</p>\n              <ol>\n                <li>Extract <code>nssm.exe</code> into the Prometheus directory.</li>\n                <li>Open PowerShell as Administrator and run:\n                  <div class=\"ibm-code-block\">\n                    <pre>A:\ncd A:\\prometheus\n.\\nssm.exe install Prometheus</pre>\n                  </div>\n                </li>\n                <li>In the NSSM GUI configuration dialog that opens:\n                  <ul>\n                    <li><strong>Path:</strong> <code>A:\\prometheus\\prometheus.exe</code></li>\n                    <li><strong>Startup directory:</strong> <code>A:\\prometheus</code></li>\n                    <li><strong>Arguments:</strong> <code>--config.file=prometheus.yml</code></li>\n                  </ul>\n                </li>\n                <li>Click **Install service**, then start the service:\n                  <div class=\"ibm-code-block\">\n                    <pre>Start-Service -Name \"Prometheus\"</pre>\n                  </div>\n                </li>\n              </ol>\n            </section>",
    "html_hi": "<h1>1.4: Prometheus Configure aur Start Karein</h1>\n            <p class=\"page-subtitle\">WebSphere metrics endpoints ko scrape karke local Prometheus database me store karein.</p>\n            \n            <section>\n              <h2>prometheus.yml Configuration</h2>\n              <p>Prometheus directory ke andar <code>prometheus.yml</code> file open karein aur scrape targets define karein:</p>\n\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>prometheus.yml</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('global:\\n  scrape_interval: 15s\\n  evaluation_interval: 15s\\n\\nscrape_configs:\\n  - job_name: \\&quot;prometheus\\&quot;\\n    static_configs:\\n      - targets: [\\&quot;localhost:9090\\&quot;]\\n\\n  - job_name: \\&quot;websphere-mxserver\\&quot;\\n    metrics_path: \\&quot;/metrics\\&quot;\\n    scheme: \\&quot;http\\&quot;\\n    static_configs:\\n      - targets:\\n          - \\&quot;localhost:9084\\&quot;', this)\"><i class=\"fa-regular fa-copy\"></i> Copy Config</button>\n                </div>\n                <pre>global:\n  scrape_interval: 15s\n  evaluation_interval: 15s\n\nscrape_configs:\n  - job_name: \"prometheus\"\n    static_configs:\n      - targets: [\"localhost:9090\"]\n\n  - job_name: 'websphere-mxserver'\n    metrics_path: '/metrics'\n    scheme: 'http'\n    static_configs:\n      - targets:\n          - 'localhost:9084'</pre>\n              </div>\n\n              <h2>Windows Service ke roop mein Setup (NSSM)</h2>\n              <p>Prometheus ko background Windows Service banane ke liye NSSM tool use karein:</p>\n              <ol>\n                <li><code>nssm.exe</code> ko Prometheus folder me copy karein.</li>\n                <li>Administrator PowerShell me navigate karke install command chalayein:\n                  <div class=\"ibm-code-block\">\n                    <pre>A:\ncd A:\\prometheus\n.\\nssm.exe install Prometheus</pre>\n                  </div>\n                </li>\n                <li>NSSM GUI popup me details fill karein:\n                  <ul>\n                    <li><strong>Path:</strong> <code>A:\\prometheus\\prometheus.exe</code></li>\n                    <li><strong>Startup directory:</strong> <code>A:\\prometheus</code></li>\n                    <li><strong>Arguments:</strong> <code>--config.file=prometheus.yml</code></li>\n                  </ul>\n                </li>\n                <li>**Install service** par click karein aur service start karein:\n                  <div class=\"ibm-code-block\">\n                    <pre>Start-Service -Name \"Prometheus\"</pre>\n                  </div>\n                </li>\n              </ol>\n            </section>"
  },
  "pmi-troubleshoot": {
    "id": "pmi-troubleshoot",
    "title": "1.5: PMI Troubleshooting & Verification Checklist",
    "title_hi": "1.5: PMI Troubleshooting aur Verification Checklist",
    "subtitle": "Verify your PMI metrics configuration and resolve virtual host errors.",
    "subtitle_hi": "PMI metrics configuration verify karein aur virtual host error (SRVE0255E) solve karein.",
    "html": "<h1>1.5: PMI Troubleshooting & Verification Checklist</h1>\n            <p class=\"page-subtitle\">Verify your PMI metrics configuration and resolve virtual host errors.</p>\n            \n            <section>\n              <h2>Troubleshooting Virtual Host Errors</h2>\n              <div class=\"ibm-callout ibm-danger\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-xmark\"></i> SRVE0255E Error</div>\n                <div class=\"ibm-callout-content\">\n                  <p><code>SRVE0255E: A WebGroup/Virtual Host to handle /metrics has not been defined.</code></p>\n                  <p>This is triggered when you try to access the metrics context using port 9043, but the application is only bound to target <code>default_host</code>.</p>\n                </div>\n              </div>\n              \n              <h3>Solution A: Query via default application port</h3>\n              <p>Connect directly to the default HTTP application port: <code>http://localhost:9081/metrics</code> (or <code>9084</code> for MXSERVER).</p>\n\n              <h3>Solution B: Update metrics virtual host mapping</h3>\n              <p>In WebSphere Enterprise Applications, select <strong>metrics</strong>, go to **Virtual hosts** properties, and switch the mapping from <code>default_host</code> to <code>admin_host</code>. Save, restart the app, and you can now scrape from port 9043.</p>\n\n              <h2 style=\"margin-top: 2.5rem;\">PMI Verification Checklist</h2>\n              <p>Verify that your WebSphere metric scraping environment is fully configured:</p>\n              \n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-pmi\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>PMI Service Active</h4>\n                  <p>PMI Enabled at the Basic level in the WebSphere console under Monitoring and Tuning.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-ear\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>metrics.ear Deployed & Running</h4>\n                  <p>Native metrics application successfully deployed and responding with raw Prometheus metrics payload on ports 9081 or 9084.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-prom\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Prometheus Scraper Active</h4>\n                  <p>Prometheus service configured inside prometheus.yml, running in the background, and scraping endpoints successfully.</p>\n                </div>\n              </label>\n            </section>",
    "html_hi": "<h1>1.5: PMI Troubleshooting aur Verification Checklist</h1>\n            <p class=\"page-subtitle\">PMI metrics configuration verify karein aur virtual host error (SRVE0255E) solve karein.</p>\n            \n            <section>\n              <h2>Virtual Host Errors Troubleshooting (SRVE0255E)</h2>\n              <div class=\"ibm-callout ibm-danger\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-xmark\"></i> SRVE0255E Error</div>\n                <div class=\"ibm-callout-content\">\n                  <p><code>SRVE0255E: A WebGroup/Virtual Host to handle /metrics has not been defined.</code></p>\n                  <p>Yeh error tab aata hai jab aap port 9043 se metrics access karne ki koshish karte hain jabki app <code>default_host</code> par bound hoti hai.</p>\n                </div>\n              </div>\n              \n              <h3>Solution A: Application Port se Query Karein</h3>\n              <p>Directly target HTTP application port use karein: <code>http://localhost:9081/metrics</code> (ya MXSERVER ke liye <code>9084</code>).</p>\n\n              <h3>Solution B: Virtual Host Mapping Update Karein</h3>\n              <p>WAS Enterprise Applications me <strong>metrics</strong> select karein, **Virtual hosts** properties me jayein, aur mapping ko <code>default_host</code> se <code>admin_host</code> par switch karein. Save aur restart karne ke baad port 9043 se bhi access ho jayega.</p>\n\n              <h2 style=\"margin-top: 2.5rem;\">PMI Verification Checklist</h2>\n              <p>Check karein ki aapka setup successfully complete ho chuka hai:</p>\n              \n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-pmi\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>PMI Service Active</h4>\n                  <p>WebSphere console me Monitoring & Tuning ke andar PMI Basic level par active hai.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-ear\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>metrics.ear Deployed & Running</h4>\n                  <p>Native metrics application successfully deployed hai aur port 9081/9084 par raw Prometheus output de rahi hai.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-websphere-prom\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Prometheus Scraper Active</h4>\n                  <p>Prometheus service prometheus.yml ke sath background me chal rahi hai aur targets <code>UP</code> status show kar rahe hain.</p>\n                </div>\n              </label>\n            </section>"
  },
  "step4": {
    "id": "step4",
    "title": "2.1: Configure WebSphere Logs Monitoring (Loki & Promtail)",
    "title_hi": "2.1: WebSphere Logs Monitoring Setup (Loki & Promtail)",
    "subtitle": "Configure log aggregation of SystemOut logs on Windows.",
    "subtitle_hi": "Windows par WebSphere SystemOut.log files ko aggregate aur ship karne ke liye Loki aur Promtail configure karein.",
    "html": "<h1>2.1: Configure WebSphere Logs Monitoring (Loki & Promtail)</h1>\n            <p class=\"page-subtitle\">Configure log aggregation of SystemOut logs on Windows.</p>\n            \n            <section>\n              <h2>Procedure</h2>\n              <p>To view real-time log outputs, deploy Loki (the log database) and Promtail (the log agent).</p>\n              \n              <h3>1. Extraction</h3>\n              <p>Extract Loki and Promtail binary distributions to a local folder, for example <code>A:\\loki</code>. Rename the binary files to <code>loki.exe</code> and <code>promtail.exe</code>.</p>\n\n              <h3>2. Configure and Run Loki</h3>\n              <p>Create the config file <code>loki-local-config.yaml</code> inside <code>A:\\loki</code>. Execute the service using PowerShell:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>PowerShell</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('cd A:\\\\loki\\n.\\\\loki.exe --config.file=loki-local-config.yaml', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                </div>\n                <pre>cd A:\\loki\n.\\loki.exe --config.file=loki-local-config.yaml</pre>\n              </div>\n\n              <h3>3. Configure and Run Promtail</h3>\n              <p>Create <code>promtail-local-config.yaml</code> inside <code>A:\\loki</code>. Map the logging path target to your profile directories:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>YAML Path Target</span>\n                </div>\n                <pre>__path__: C:\\IBM\\WebSphere\\AppServer\\profiles\\*\\logs\\*\\SystemOut.log</pre>\n              </div>\n              <p>Start Promtail in a separate terminal window:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>PowerShell</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('cd A:\\\\loki\\n.\\\\promtail.exe --config.file=promtail-local-config.yaml', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                </div>\n                <pre>cd A:\\loki\n.\\promtail.exe --config.file=promtail-local-config.yaml</pre>\n              </div>\n\n              <h3>4. Setup Windows Background Services (Loki & Promtail)</h3>\n              <p>To run Loki and Promtail persistently in the background without keeping active PowerShell windows open, register them as Windows Services using NSSM:</p>\n              \n              <h4>A. Extract NSSM Utility</h4>\n              <p>Download NSSM utility and extract <code>nssm.exe</code> into your Loki directory (e.g. <code>A:\\loki</code>).</p>\n\n              <h4>B. Install Loki Service</h4>\n              <ol>\n                <li>Open PowerShell as Administrator and execute:\n                  <div class=\"ibm-code-block\">\n                    <pre>A:\ncd A:\\loki\n.\\nssm.exe install Loki</pre>\n                  </div>\n                </li>\n                <li>In the NSSM GUI configuration dialog:\n                  <ul>\n                    <li><strong>Path:</strong> <code>A:\\loki\\loki.exe</code></li>\n                    <li><strong>Startup directory:</strong> <code>A:\\loki</code></li>\n                    <li><strong>Arguments:</strong> <code>--config.file=loki-local-config.yaml</code></li>\n                  </ul>\n                </li>\n                <li>Click **Install service**, then start:\n                  <div class=\"ibm-code-block\">\n                    <pre>Start-Service -Name \"Loki\"</pre>\n                  </div>\n                </li>\n              </ol>\n\n              <h4>C. Install Promtail Service</h4>\n              <ol>\n                <li>In the same PowerShell Administrator window, execute:\n                  <div class=\"ibm-code-block\">\n                    <pre>.\\nssm.exe install Promtail</pre>\n                  </div>\n                </li>\n                <li>In the NSSM GUI configuration dialog:\n                  <ul>\n                    <li><strong>Path:</strong> <code>A:\\loki\\promtail.exe</code></li>\n                    <li><strong>Startup directory:</strong> <code>A:\\loki</code></li>\n                    <li><strong>Arguments:</strong> <code>--config.file=promtail-local-config.yaml</code></li>\n                  </ul>\n                </li>\n                <li>Click **Install service**, then start:\n                  <div class=\"ibm-code-block\">\n                    <pre>Start-Service -Name \"Promtail\"</pre>\n                  </div>\n                </li>\n              </ol>\n            </section>",
    "html_hi": "<h1>2.1: WebSphere Logs Monitoring Setup (Loki & Promtail)</h1>\n            <p class=\"page-subtitle\">Windows par WebSphere SystemOut.log files ko aggregate aur ship karne ke liye Loki aur Promtail configure karein.</p>\n            \n            <section>\n              <h2>Step-by-Step Procedure</h2>\n              <p>Real-time logs analyze karne ke liye hum Loki (log database) aur Promtail (log shipper agent) deploy karte hain.</p>\n              \n              <h3>1. Binaries Extract Karein</h3>\n              <p>Loki aur Promtail ko local folder (jaise <code>A:\\loki</code>) me extract karein aur executables ko <code>loki.exe</code> aur <code>promtail.exe</code> rename karein.</p>\n\n              <h3>2. Loki Configure aur Start Karein</h3>\n              <p><code>A:\\loki\\loki-local-config.yaml</code> config file create karein aur run karein:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>PowerShell</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('cd A:\\\\loki\\n.\\\\loki.exe --config.file=loki-local-config.yaml', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                </div>\n                <pre>cd A:\\loki\n.\\loki.exe --config.file=loki-local-config.yaml</pre>\n              </div>\n\n              <h3>3. Promtail Configure aur Run Karein</h3>\n              <p><code>promtail-local-config.yaml</code> create karein aur WebSphere log directory map karein:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>Log Path Config</span>\n                </div>\n                <pre>__path__: C:\\IBM\\WebSphere\\AppServer\\profiles\\*\\logs\\*\\SystemOut.log</pre>\n              </div>\n              <p>Promtail start karein:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>PowerShell</span>\n                  <button class=\"btn-copy\" onclick=\"copyText('cd A:\\\\loki\\n.\\\\promtail.exe --config.file=promtail-local-config.yaml', this)\"><i class=\"fa-regular fa-copy\"></i> Copy</button>\n                </div>\n                <pre>cd A:\\loki\n.\\promtail.exe --config.file=promtail-local-config.yaml</pre>\n              </div>\n\n              <h3>4. Windows Background Services Setup (NSSM)</h3>\n              <p>Dono processes ko background services banane ke liye NSSM use karein:</p>\n              <ol>\n                <li><code>A:\\loki</code> me Administrator PowerShell open karein.</li>\n                <li>Loki service install karein:\n                  <div class=\"ibm-code-block\">\n                    <pre>.\\nssm.exe install Loki</pre>\n                  </div>\n                  Path: <code>A:\\loki\\loki.exe</code> | Arguments: <code>--config.file=loki-local-config.yaml</code>\n                </li>\n                <li>Promtail service install karein:\n                  <div class=\"ibm-code-block\">\n                    <pre>.\\nssm.exe install Promtail</pre>\n                  </div>\n                  Path: <code>A:\\loki\\promtail.exe</code> | Arguments: <code>--config.file=promtail-local-config.yaml</code>\n                </li>\n                <li>Services start karein:\n                  <div class=\"ibm-code-block\">\n                    <pre>Start-Service -Name \"Loki\"\nStart-Service -Name \"Promtail\"</pre>\n                  </div>\n                </li>\n              </ol>\n            </section>"
  },
  "step5": {
    "id": "step5",
    "title": "2.2: Configure Grafana Visualizations",
    "title_hi": "2.2: Grafana Visualizations Configure Karein",
    "subtitle": "Connect datasets and render metrics dashboards.",
    "subtitle_hi": "Prometheus aur Loki datasets ko Grafana se connect karein aur pre-built dashboards import karein.",
    "html": "<h1>2.2: Configure Grafana Visualizations</h1>\n            <p class=\"page-subtitle\">Connect datasets and render metrics dashboards.</p>\n            \n            <section>\n              <h2>Configuring Data Sources</h2>\n              <ol>\n                <li>Open your Grafana browser UI at <code>http://localhost:3000</code>.</li>\n                <li>Navigate to **Connections** &gt; **Data Sources** &gt; Click **Add data source**.</li>\n                <li>Select **Prometheus**. Set the URL connection string to: <code>http://localhost:9090</code>. Save and test.</li>\n                <li>Select **Loki**. Set the URL connection string to: <code>http://localhost:3100</code>. Save and test.</li>\n              </ol>\n\n              <h2>Importing Dashboards</h2>\n              <ol>\n                <li>Navigate to **Dashboards** &gt; **New** &gt; **Import**.</li>\n                <li>Input Dashboard ID **<code>14151</code>** (or upload the local WAS dashboard template JSON file).</li>\n                <li>Select the Prometheus data source in the dropdown selector and click **Import**.</li>\n              </ol>\n            </section>",
    "html_hi": "<h1>2.2: Grafana Visualizations Configure Karein</h1>\n            <p class=\"page-subtitle\">Prometheus aur Loki datasets ko Grafana se connect karein aur pre-built dashboards import karein.</p>\n            \n            <section>\n              <h2>Data Sources Setup Karna</h2>\n              <ol>\n                <li>Browser me Grafana UI open karein: <code>http://localhost:3000</code></li>\n                <li>**Connections** &gt; **Data Sources** &gt; Click **Add data source**.</li>\n                <li>**Prometheus** select karein. URL set karein: <code>http://localhost:9090</code>. Click **Save &amp; test**.</li>\n                <li>**Loki** select karein. URL set karein: <code>http://localhost:3100</code>. Click **Save &amp; test**.</li>\n              </ol>\n\n              <h2>Pre-built WebSphere Dashboards Import Karna</h2>\n              <ol>\n                <li>**Dashboards** &gt; **New** &gt; **Import** par jayein.</li>\n                <li>Dashboard ID field mein **<code>14151</code>** enter karein (ya local JSON file upload karein).</li>\n                <li>Dropdown selector mein Prometheus data source choose karein aur **Import** click karein.</li>\n              </ol>\n            </section>"
  },
  "logs-troubleshoot": {
    "id": "logs-troubleshoot",
    "title": "2.3: Logs Troubleshooting & Verification Checklist",
    "title_hi": "2.3: Logs Troubleshooting aur Verification Checklist",
    "subtitle": "Resolve log aggregation issues and verify shipping status.",
    "subtitle_hi": "Loki storage issues resolve karein aur logs shipping status verify karein.",
    "html": "<h1>2.3: Logs Troubleshooting & Verification Checklist</h1>\n            <p class=\"page-subtitle\">Resolve log aggregation issues and verify shipping status.</p>\n            \n            <section>\n              <h2>Troubleshooting Loki Storage & Crashes</h2>\n              <div class=\"ibm-callout ibm-danger\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-xmark\"></i> Write Permissions Failure</div>\n                <div class=\"ibm-callout-content\">\n                  <p>Loki fails with directory creation errors when attempting to write database chunk files to the root level of drive partitions (e.g. <code>A:\\tmp\\loki</code>).</p>\n                </div>\n              </div>\n              \n              <h3>Solution: Relocate Loki storage path</h3>\n              <p>Modify your <code>loki-local-config.yaml</code> paths to point to a writable user subdirectory:</p>\n              <div class=\"ibm-code-block\">\n                <pre>common:\n  path_prefix: A:\\loki\\data</pre>\n              </div>\n\n              <h2 style=\"margin-top: 2.5rem;\">Logs & Visualizations Checklist</h2>\n              <p>Ensure that WebSphere logs are correctly ingested and visual data sources are connected:</p>\n              \n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-loki-run\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Loki Log Database Active</h4>\n                  <p>Loki service started successfully on port 3100 without write permission crashes.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-promtail-run\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Promtail Log Shipper Active</h4>\n                  <p>Promtail is tailing SystemOut.log from profile directories and streaming logs into Loki.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-grafana-conn\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Grafana Data Sources Verified</h4>\n                  <p>Both Prometheus (port 9090) and Loki (port 3100) data sources tested successfully in Grafana UI.</p>\n                </div>\n              </label>\n            </section>",
    "html_hi": "<h1>2.3: Logs Troubleshooting aur Verification Checklist</h1>\n            <p class=\"page-subtitle\">Loki storage issues resolve karein aur logs shipping status verify karein.</p>\n            \n            <section>\n              <h2>Loki Storage Crashes & Permission Issues Solve Karna</h2>\n              <div class=\"ibm-callout ibm-danger\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-xmark\"></i> Write Permissions Failure</div>\n                <div class=\"ibm-callout-content\">\n                  <p>Loki crash ho jata hai jab woh drive ke root level par chunk directories create karne ki koshish karta hai (e.g. <code>A:\\tmp\\loki</code>).</p>\n                </div>\n              </div>\n              \n              <h3>Solution: Loki Storage Path Update Karein</h3>\n              <p><code>loki-local-config.yaml</code> mein paths ko specific writable subdirectory par point karein:</p>\n              <div class=\"ibm-code-block\">\n                <pre>common:\n  path_prefix: A:\\loki\\data</pre>\n              </div>\n\n              <h2 style=\"margin-top: 2.5rem;\">Logs aur Visualizations Checklist</h2>\n              <p>Ensure karein ki aapka logs pipeline properly working hai:</p>\n              \n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-loki-run\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Loki Database Active</h4>\n                  <p>Loki service bina kisi permission crash ke port 3100 par smoothly chal rahi hai.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-promtail-run\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Promtail Shipper Active</h4>\n                  <p>Promtail WebSphere profile se <code>SystemOut.log</code> tail karke Loki ko real-time feed bhej raha hai.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-grafana-conn\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Grafana Data Sources Verified</h4>\n                  <p>Prometheus (port 9090) aur Loki (port 3100) dono data sources Grafana UI me **Working** test ho chuke hain.</p>\n                </div>\n              </label>\n            </section>"
  }
};
